"""Verify a Genesee Press demo release tree (generated by synthetic-enterprise SYNTH-CUTOVER-01).

    python3 demo-release/verify_release.py [ROOT]

Standard library only. Fails (exit 1) when:

* ``demo-release.json`` is missing a provenance field, or its lock record does not match the
  vendoring lock file in the tree;
* any file differs from ``demo-release/files.sha256``, or a file was added or removed (in a Git
  checkout: the committed files at HEAD, and no tracked file may be modified; otherwise every
  file outside ``.git``);
* a prohibited file type is present (environment files with values, keys, local databases,
  caches, dependency directories).

The release is a one-way mirror: the fix for a failure is a new export upstream, never an edit
here.
"""

from __future__ import annotations

import hashlib
import json
import re
import subprocess
import sys
from pathlib import Path

REQUIRED = (
    "application",
    "release_id",
    "application_upstream_sha",
    "synthetic_enterprise_sha",
    "synthetic_dataset_version",
    "synthetic_contract_version",
    "projection_version",
    "generated_at",
    "source_branch",
    "vendoring_lock",
)
SHA = re.compile(r"^[0-9a-f]{40}$")
PROHIBITED = re.compile(
    r"(^|/)(\.env(\.(?!example$)[^/]+)?|\.dev\.vars[^/]*|[^/]+\.(pem|key|p12|pfx|jks|keystore|sqlite3?|db|dump|bak|pyc|log)"
    r"|id_(rsa|ed25519|ecdsa)[^/]*|\.DS_Store|\.npmrc|\.pypirc|\.netrc)$"
    r"|(^|/)(node_modules|__pycache__|\.venv|venv|\.pytest_cache|\.mypy_cache|\.ruff_cache|\.next|\.wrangler|\.tmp|\.idea|\.vscode)/"
)


def committed(root: Path) -> dict[str, bytes] | None:
    """In a Git checkout: every tracked file as committed at HEAD (the blob, before any checkout
    filter such as ``eol=crlf`` in ``.gitattributes``). ``None`` outside Git."""
    if not (root / ".git").exists():
        return None
    run = lambda *a: subprocess.run(["git", "-C", str(root), *a], capture_output=True, check=True).stdout  # noqa: E731
    entries = [line.split(b"\t", 1) for line in run("ls-tree", "-r", "-z", "HEAD").split(b"\0") if line]
    objects = {path.decode(): meta.split()[2].decode() for meta, path in entries}
    proc = subprocess.run(
        ["git", "-C", str(root), "cat-file", "--batch"],
        input="".join(f"{o}\n" for o in objects.values()).encode(),
        capture_output=True,
        check=True,
    ).stdout
    blobs, pos = {}, 0
    while pos < len(proc):
        header_end = proc.index(b"\n", pos)
        obj, _kind, size = proc[pos:header_end].split()
        start = header_end + 1
        blobs[obj.decode()] = proc[start : start + int(size)]
        pos = start + int(size) + 1
    return {path: blobs[obj] for path, obj in objects.items()}


def files_of(root: Path) -> dict[str, bytes]:
    tree = committed(root)
    if tree is not None:
        return tree
    return {
        p.relative_to(root).as_posix(): p.read_bytes() for p in root.rglob("*") if p.is_file() and ".git" not in p.relative_to(root).parts
    }


def main(argv: list[str]) -> int:
    root = Path(argv[1] if len(argv) > 1 else Path(__file__).resolve().parents[1])
    errors: list[str] = []
    provenance = json.loads((root / "demo-release.json").read_text(encoding="utf-8"))
    for key in REQUIRED:
        if not provenance.get(key):
            errors.append(f"demo-release.json: missing {key}")
    for key in ("application_upstream_sha", "synthetic_enterprise_sha"):
        if not SHA.match(str(provenance.get(key, ""))):
            errors.append(f"demo-release.json: {key} is not a full commit SHA")

    lock_record = provenance.get("vendoring_lock", {})
    lock_path = root / lock_record.get("path", "")
    if not lock_path.is_file():
        errors.append(f"vendoring lock missing: {lock_record.get('path')}")
    else:
        data = lock_path.read_bytes()
        lock = json.loads(data)
        if hashlib.sha256(data).hexdigest() != lock_record.get("sha256"):
            errors.append("vendoring lock differs from the recorded digest")
        if lock.get("commit") != lock_record.get("commit"):
            errors.append("vendoring lock commit differs from demo-release.json")
        if lock.get("dataset") != f"synthetic-enterprise-world@{provenance.get('synthetic_dataset_version')}":
            errors.append("vendoring lock dataset differs from demo-release.json")
        if lock.get("projection") != provenance.get("projection_version"):
            errors.append("vendoring lock projection differs from demo-release.json")
        if lock.get("contract_version") != provenance.get("synthetic_contract_version"):
            errors.append("vendoring lock contract differs from demo-release.json")

    listing = root / "demo-release" / "files.sha256"
    expected: dict[str, str] = {}
    for line in listing.read_text(encoding="utf-8").splitlines():
        digest, path = line.split("  ", 1)
        expected[path] = digest
    tree = files_of(root)
    actual = [p for p in tree if p != "demo-release/files.sha256"]
    for path in sorted(set(actual) - set(expected)):
        errors.append(f"not in the release: {path}")
    for path in sorted(set(expected) - set(actual)):
        errors.append(f"missing from the tree: {path}")
    for path in sorted(set(actual) & set(expected)):
        if hashlib.sha256(tree[path]).hexdigest() != expected[path]:
            errors.append(f"changed after release: {path}")
    if (root / ".git").exists():
        dirty = subprocess.run(["git", "-C", str(root), "status", "--porcelain", "--untracked-files=no"], capture_output=True, check=True)
        for line in dirty.stdout.decode().splitlines():
            errors.append(f"modified in this checkout: {line[3:]}")
    for path in actual:
        if PROHIBITED.search(path):
            errors.append(f"prohibited file: {path}")

    if errors:
        for e in errors[:200]:
            print(f"FAIL {e}")
        print(f"{len(errors)} problem(s): this tree is not the recorded release {provenance.get('release_id')}")
        return 1
    print(
        f"OK {provenance['release_id']}: {len(expected)} files match; "
        f"{provenance['application']} @ {provenance['application_upstream_sha'][:12]}, "
        f"synthetic-enterprise @ {provenance['synthetic_enterprise_sha'][:12]}, "
        f"{provenance['projection_version']}, dataset {provenance['synthetic_dataset_version']}"
    )
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
